Contract GenerateLoanLetterAndAgreementModule::createLoanAccount(loanaccountid:Integer,balance:Real,status:LoanAccountStatus[NORMAL|HASPAIDINFULL]): Boolean {
          definition:
          existingAccount:LoanAccount = LoanAccount.allInstance()->any(o | o.LoanAccountID=loanaccountid)


            postcondition:
          if existingAccount.oclIsUndefined() then let newAccount:LoanAccount in newAccount.oclIsNew() and newAccount.LoanAccountID=loanaccountid and newAccount.Balance=balance and newAccount.Status=status and LoanAccount.allInstance()->includes(newAccount) else true endif and result=true

        }
